class TmnxSubActivityThreshold(TextualConvention, Unsigned32):
    description = 'The TmnxSubActivityThreshold data type is an unsigned number that\n         indicates the threshold in Kbps that is applied to determine if a\n         subscriber is active.\n\n         If the traffic volume is below the threshold, the subscriber is idle.\n\n         Otherwise, the subscriber is active.'
    status = 'current'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(0, 100000000)

