tmnxSubAuthPlcyUserNameOp = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 33, 1, 1, 1, 31), TmnxSubAuthPlcyUserNameOp().clone('noOperation')).setMaxAccess("readcreate")
