tmnxSubMngdHostCreationFail = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 33, 0, 34)).setObjects(("TIMETRA-SERV-MIB", "svcId"), ("TIMETRA-SAP-MIB", "sapPortId"), ("TIMETRA-SAP-MIB", "sapEncapValue"), ("TIMETRA-SUBSCRIBER-MGMT-MIB", "tmnxSubNotifIpAddrType"), ("TIMETRA-SUBSCRIBER-MGMT-MIB", "tmnxSubNotifIpAddr"), ("TIMETRA-SUBSCRIBER-MGMT-MIB", "tmnxSubNotifMacAddr"), ("TIMETRA-SUBSCRIBER-MGMT-MIB", "tmnxSubAdditionalInfo"))
